try:
    # Create a safe data generator wrapper that handles corrupted files
    def safe_generator(generator, max_skips=100):
        """Generator wrapper that skips batches with corrupted files."""
        skip_count = 0
        while True:
            if skip_count >= max_skips:
                # Give up and generate dummy data if too many skips
                raise StopIteration("Too many corrupted files")
            try:
                batch = next(generator)
                yield batch
            except StopIteration:
                raise
            except Exception as e:
                skip_count += 1
                if skip_count % 10 == 0:
                    print(f"Warning: Skipping batch {skip_count} due to error")
                continue

